<?php
declare(strict_types=1);require __DIR__.'/../lib/core.php';if(PHP_SAPI!=='cli'){http_response_code(403);exit("CLI only\n");}$db=x1_db();if(!$db){fwrite(STDERR,"PDO SQLite required\n");exit(2);}$worker=gethostname().':'.getmypid();$limit=max(1,min(100,(int)($argv[1]??10)));for($i=0;$i<$limit;$i++){$db->beginTransaction();try{$job=x1_db_one("SELECT * FROM jobs WHERE status='pending' AND run_after<=? ORDER BY priority ASC,created_at ASC LIMIT 1",[date('c')]);if(!$job){$db->commit();break;}x1_db_exec("UPDATE jobs SET status='running',locked_at=?,locked_by=?,attempts=attempts+1,updated_at=? WHERE id=? AND status='pending'",[date('c'),$worker,date('c'),$job['id']]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}try{$payload=json_decode((string)$job['payload_json'],true)?:[];switch($job['type']){case'health_check':$result=x1_health_checks();foreach($result as $c)if(!$c['ok']){x1_notify('warning','Health check failed',$c['name'].': '.$c['detail']);x1_integration_send('health_failed','X1 WAVEO health warning',$c['name'].': '.$c['detail'],$c);}break;case'notification':$title=(string)($payload['title']??'X1 WAVEO');$body=(string)($payload['body']??'');x1_notify((string)($payload['level']??'info'),$title,$body,$payload);$result=x1_integration_send('notification',$title,$body,$payload);break;case'backup':$src=x1_db_path();$dest=X1_ROOT.'/storage/backups/x1-waveo-worker-'.date('Ymd-His').'.sqlite';if(!copy($src,$dest))throw new RuntimeException('backup copy failed');$result=['file'=>basename($dest)];break;default:$result=['accepted'=>true,'type'=>$job['type'],'payload'=>$payload];}x1_db_exec("UPDATE jobs SET status='done',last_error='',updated_at=?,finished_at=? WHERE id=?",[date('c'),date('c'),$job['id']]);echo $job['id']." done\n";}catch(Throwable $e){$attempt=(int)x1_db_scalar('SELECT attempts FROM jobs WHERE id=?',[$job['id']],1);$max=(int)$job['max_attempts'];$status=$attempt>=$max?'failed':'pending';$delay=min(3600,30*(2**max(0,$attempt-1)));$run=date('c',time()+$delay);x1_db_exec("UPDATE jobs SET status=?,last_error=?,run_after=?,locked_at=NULL,locked_by=NULL,updated_at=? WHERE id=?",[$status,substr($e->getMessage(),0,2000),$run,date('c'),$job['id']]);echo $job['id']." ".$status."\n";}}